  /// array param reserves one positional per trailing param; regular
  /// params take one value each; extra positionals are ignored. Tools
  /// without params fall back to `arg0`, `arg1`, …
  static void _mapPositionalArguments(
      Map<String, dynamic> args, List<ToolParam> params, List<String> pos) {
    final value = i + 1 < _args.length ? _args[i + 1] : '';
    _applyValueFlag(arg, value);
    return 2;
  }

  /// Applies a boolean flag or collects a non-flag positional token.
  void _applyBooleanOrPositional(String arg) {
    switch (arg) {
      case '--verbose':
        _verbose = true;
      case '--debug':
        _verbose = true;
        _debug = true;
      case '--quiet':
        _quiet = true;
      case '--toon':
